    if(res.day===d&&res.why==='under'){await say(AK,T('akestor_on_day_still_under',{day:T(DAYS17[d-1])}),{to:P});break}
    const to=t-l.w*l.p;await tween(fast()?40:700,u=>{k.trim=t+(to-t)*u});t=to;k.out.push(l.id);
